import Foundation

/// A school whose Blackboard address is known.
struct KnownSchool: Equatable {
    let name: String
    let url: String
    let domain: String
    let localNames: [String]
    let aliases: [String]
}

/// The desktop app's list of schools (`src/blackboard_sync/schools.py`): a name, an abbreviation or a web
/// domain typed in the address field becomes the school's Blackboard address.
enum Schools {
