    /// The same steps as `fold` in `schools.py`: no accents or marks, lower case, one space between words.
    static func fold(_ text: String) -> String {
        let scalars = text.decomposedStringWithCompatibilityMapping.unicodeScalars
            .filter { $0.properties.generalCategory != .nonspacingMark }
        let bare = String(String.UnicodeScalarView(scalars)).lowercased()
            .replacingOccurrences(of: "ı", with: "i")
            .replacingOccurrences(of: "ة", with: "ه")
            .replacingOccurrences(of: "ى", with: "ي")
            .replacingOccurrences(of: "ـ", with: "")
        let letters = bare.unicodeScalars.map { CharacterSet.alphanumerics.contains($0) ? Character($0) : " " }
        return String(letters).split(separator: " ").joined(separator: " ")
    }

    private static let index: [String: KnownSchool] = {
        var index: [String: KnownSchool] = [:]
        for school in all {
            let host = URL(string: school.url)?.host ?? ""
            for key in [school.name] + school.localNames + school.aliases + [school.domain, host] {
                let folded = fold(key)
                if index[folded] == nil { index[folded] = school }
            }
        }
        return index
    }()

    /// The school meant by `text`: its name, abbreviation, web domain or Blackboard host. Text with a
    /// scheme is already an address, so it names no school.
    static func find(_ text: String) -> KnownSchool? {
        let text = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty, !text.contains("://") else { return nil }
        return index[fold(text)]
    }

    /// The Blackboard address of the school `text` names, or nil.
    static func resolve(_ text: String) -> URL? {
        find(text).flatMap { URL(string: $0.url) }
    }
}
